use bevy::prelude::*;

#[derive(Component)] struct Guard { x: f32 }

fn patrol(time: Res<Time>, mut q: Query<&mut Guard>) {
    for mut guard in &mut q {                       // system walks its query
        guard.x += 20.0 * time.delta_secs();
    }
}

App::new().add_systems(Update, patrol).run();       // once per render frame
